## Code Example

```javascript
import { test, expect } from '@playwright/test';

test('data export flow is idempotent', async ({ page }) => {
  await page.goto('/dashboard');

  await seedTestData({ userId: 'user-123', dataset: [...] });

  await page.fill('#date-from', '2024-01-01');
  await page.fill('#date-to', '2024-01-31');
  await page.selectOption('#status', 'completed');

  await page.click('#export-btn');

  await page.route('**/api/export', async (route) => {
    await route.fulfill({ status: 200, body: { jobId: 'job-123', status: 'completed' } });
  });

  await page.route('**/api/email/send', async (route) => {
    await route.fulfill({ status: 200 });
  });

  await expect(page.locator('#download-link')).toBeVisible({ timeout: 10000 });

  const emailRequests = [];
  await page.on('request', (req) => {
    if (req.url().includes('/api/email/send')) {
      emailRequests.push(req);
    }
  });

  await page.click('#export-btn');
  await page.waitForTimeout(500);

  expect(emailRequests).toHaveLength(1);
});
```

